}

// MarshalBatch encodes normalized events as a JSON array with sorted keys.
func MarshalBatch(batch []Event) ([]byte, error) {
	dtos := make([]eventDTO, len(batch))
	for i, event := range batch {
		dtos[i] = eventDTO{
			ID:       event.ID,
			Service:  event.Service,
			Severity: event.Severity,
			Message:  event.Message,
			At:       event.At,
			Labels:   event.Labels,
		}
	}
	return json.Marshal(dtos)
}

// DecodeBatch strictly decodes a JSON array of events. Unknown fields, syntax
// errors, malformed timestamps, malformed labels, and trailing data are
// rejected; callers remain responsible for emptiness and field validation.
func DecodeBatch(data []byte) ([]Event, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	var dtos []rawEventDTO
	if err := dec.Decode(&dtos); err != nil {
		return nil, fmt.Errorf("decode events array: %w", err)
	}
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != io.EOF {
		if err == nil {
			return nil, fmt.Errorf("decode events array: unexpected trailing data")
		}
		return nil, fmt.Errorf("decode events array: %w", err)
	}
	batch := make([]Event, len(dtos))
	for i, dto := range dtos {
		labels, err := decodeLabels(dto.Labels)
		if err != nil {
			return nil, err
		}
		batch[i] = Event{
			ID:       dto.ID,
			Service:  dto.Service,
			Severity: dto.Severity,
			Message:  dto.Message,
			At:       dto.At,
			Labels:   labels,
		}
	}
	return batch, nil
}

package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/cocosolocoder/signalroom/internal/events"
	"github.com/cocosolocoder/signalroom/internal/httpapi"
	"github.com/cocosolocoder/signalroom/internal/logfile"
)

func runServe(args []string) error {
	fs := flag.NewFlagSet("serve", flag.ContinueOnError)
	addr := fs.String("addr", ":8080", "listen address")
	dataDir := fs.String("data", "", "directory for durable event data")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if *dataDir == "" || fs.NArg() != 0 {
		fmt.Fprintln(os.Stderr, "usage: signalroom serve --addr <address> --data <directory>")
		os.Exit(2)
	}

	log, batches, err := logfile.Open(*dataDir)
	if err != nil {
		return err
	}
	defer log.Close()

	timeline := events.NewTimeline()
	for _, batch := range batches {
		for _, event := range batch {
			if err := timeline.Load(event); err != nil {
				return fmt.Errorf("recover events: %w", err)
			}
		}
	}
	timeline.SortAll()

	listener, err := net.Listen("tcp", *addr)
	if err != nil {
		return fmt.Errorf("listen on %s: %w", *addr, err)
	}

	server := &http.Server{
		Handler:           httpapi.NewHandler(timeline, log, log),
		ReadHeaderTimeout: 10 * time.Second,
	}
	serverErr := make(chan error, 1)
	go func() {
		serverErr <- server.Serve(listener)
	}()

	// Published exactly once the socket accepts connections; clients (and
	// tests) can wait on this line instead of polling with fixed sleeps.
	fmt.Printf("signalroom: listening on %s\n", listener.Addr())

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)
	select {
	case sig := <-stop:
		fmt.Fprintf(os.Stderr, "signalroom: received %s, shutting down\n", sig)
	case err := <-serverErr:
		if !errors.Is(err, http.ErrServerClosed) {
			return fmt.Errorf("serve: %w", err)
		}
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	return nil
}

