35		}
36	
37		key := make([]byte, keySize)
38		if _, err := rand.Read(key); err != nil {
39			return nil, fmt.Errorf("generate cursor key: %w", err)
40		}
41		tmp := path + ".tmp"
42		if err := os.WriteFile(tmp, key, 0o600); err != nil {
43			return nil, fmt.Errorf("write cursor key: %w", err)
44		}
45		if err := os.Rename(tmp, path); err != nil {
