54	// CursorKey returns the stable per-directory key used to sign cursors.
55	func (l *Log) CursorKey() []byte {
56		return l.key
57	}
58	
59	// SaveSnapshot durably writes one query snapshot under its random id. The
60	// write is atomic (temp file, rename, directory fsync), so a crash leaves
61	// either the previous state or the complete new file.
62	func (l *Log) SaveSnapshot(id string, payload []byte) error {
63		if !isSnapshotID(id) {
64			return errors.New("invalid snapshot id")
65		}
66		dir := filepath.Join(l.dir, snapshotsDir)
67		if err := os.MkdirAll(dir, 0o755); err != nil {
68			return fmt.Errorf("create snapshots directory: %w", err)
69		}
70		final := filepath.Join(dir, id+".json")
71		tmp := filepath.Join(dir, id+".tmp")
72		if err := os.WriteFile(tmp, payload, 0o644); err != nil {
73			return fmt.Errorf("write snapshot: %w", err)
74		}
75		if err := os.Rename(tmp, final); err != nil {
76			return fmt.Errorf("write snapshot: %w", err)
77		}
78		if err := syncDir(dir); err != nil {
79			return fmt.Errorf("sync snapshots directory: %w", err)
80		}
81		return nil
82	}
83	
84	// LoadSnapshot reads a previously saved query snapshot.
85	func (l *Log) LoadSnapshot(id string) ([]byte, error) {
86		if !isSnapshotID(id) {
87			return nil, errors.New("invalid snapshot id")
88		}
89		data, err := os.ReadFile(filepath.Join(l.dir, snapshotsDir, id+".json"))
90		if err != nil {
91			return nil, fmt.Errorf("read snapshot: %w", err)
92		}
93		return data, nil
94	}
