300	// buildPageQuery parses and normalizes the same filters GET /events accepts.
301	func buildPageQuery(values url.Values) (events.Query, error) {
302		labels, err := events.ParseLabelConditions(values["label"])
303		if err != nil {
304			return events.Query{}, err
305		}
306		q := events.Query{
307			Service:  values.Get("service"),
308			Severity: values.Get("severity"),
309			Labels:   labels,
310		}
311		if raw := values.Get("since"); raw != "" {
312			parsed, err := time.Parse(time.RFC3339Nano, raw)
313			if err != nil {
314				return events.Query{}, errors.New("since must be an RFC3339Nano timestamp")
315			}
316			q.Since = parsed
317		}
318		if raw := values.Get("until"); raw != "" {
319			parsed, err := time.Parse(time.RFC3339Nano, raw)
320			if err != nil {
321				return events.Query{}, errors.New("until must be an RFC3339Nano timestamp")
322			}
323			q.Until = parsed
324		}
325		if !q.Since.IsZero() && !q.Until.IsZero() && q.Since.After(q.Until) {
326			return events.Query{}, errors.New("since must not be after until")
327		}
328		return q, nil
329	}
330	
331	// anyFilterPresent reports whether the request carries any filter parameter,
332	// which switches a continuation from "reuse the first page's filters" to
333	// "check the full filter set".
334	func anyFilterPresent(values url.Values) bool {
335		for _, name := range []string{"service", "severity", "since", "until", "label"} {
336			if _, ok := values[name]; ok {
337				return true
338			}
339		}
340		return false
341	}
342	
343	// parsePageLimit returns the limit, defaulting to defaultPageLimit when
344	// omitted. Empty, repeated, or out-of-range values are rejected.
345	func parsePageLimit(values url.Values) (int, error) {
346		vs, present := values["limit"]
347		if !present {
348			return defaultPageLimit, nil
349		}
350		if len(vs) != 1 {
351			return 0, errors.New("limit must be an integer from 1 to 1000")
352		}
353		raw := vs[0]
354		if raw == "" || !isDecimal(raw) {
355			return 0, errors.New("limit must be an integer from 1 to 1000")
356		}
357		n, err := strconv.Atoi(raw)
358		if err != nil || n < 1 || n > maxPageLimit {
359			return 0, errors.New("limit must be an integer from 1 to 1000")
360		}
361		return n, nil
362	}
363	
364	// newSnapshotID returns a random hex id for one query snapshot.
365	func newSnapshotID() (string, error) {
366		var b [16]byte
367		if _, err := rand.Read(b[:]); err != nil {
368			return "", err
369		}
370		return hex.EncodeToString(b[:]), nil
371	}
