	status, raw = httpDo(t, http.MethodGet, "http://"+p.addr+"/events?since=bad", "")
	if status != http.StatusBadRequest {
		t.Fatalf("status %d", status)
	}
	if err := json.Unmarshal(raw, &errBody); err != nil || errBody["error"] == "" {
