	failNext bool
	poisoned bool
	appended []int

	cursorKey []byte
	snapshots map[string][]byte
}

func (f *fakeStorage) Append(batch []events.Event) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.poisoned {
		return errors.New("poisoned")
	}
	if f.failNext {
		f.poisoned = true
		f.failNext = false
		return errors.New("simulated write failure")
	}
	f.appended = append(f.appended, len(batch))
	return nil
}

