// Package incidents holds the incident-handling register: incidents are
// created once, evolve through append-only actions under optimistic
// concurrency, and link back to events without modifying them.
package incidents

import (
	"errors"
	"maps"
	"slices"
	"strings"
	"sync"
	"time"
)

// Statuses an incident moves between.
const (
	StatusOpen     = "open"
	StatusResolved = "resolved"
)

// Action types accepted by POST /incidents/{id}/actions.
const (
	ActionNote      = "add_note"
	ActionLinkEvent = "link_event"
	ActionResolve   = "resolve"
	ActionReopen    = "reopen"
)

// Sentinel errors map to specific HTTP statuses at the boundary.
var (
	// ErrValidation marks missing fields, wrong types, or unknown actions.
	ErrValidation = errors.New("invalid incident request")
	// ErrNotFound marks a missing incident or, for a link, a missing event.
	ErrNotFound = errors.New("not found")
	// ErrConflict marks an id clash, a stale version, a wrong state, a
	// duplicate or incompatible link, or a replayed request whose content
	// differs from the first successful submission.
	ErrConflict = errors.New("conflict")
)

// ValidationError reports that input failed normalization or validation.
type ValidationError struct{ Reason string }

func (e *ValidationError) Error() string { return e.Reason }

func validationErr(format string, args ...any) error {
	return &ValidationError{Reason: "incident: " + fmtSprintf(format, args...)}
}

// NotFoundError reports that a referenced incident or event does not exist.
type NotFoundError struct{ Reason string }

func (e *NotFoundError) Error() string { return e.Reason }

func notFoundErr(format string, args ...any) error {
	return &NotFoundError{Reason: "incident: " + fmtSprintf(format, args...)}
}

// ConflictError carries the current incident version alongside the reason,
// so a stale-version response can report it. CurrentVersion is zero when the
// conflict is not version-related.
type ConflictError struct {
	Reason         string
	CurrentVersion int
}

func (e *ConflictError) Error() string { return e.Reason }

func conflictErr(currentVersion int, format string, args ...any) error {
	return &ConflictError{
		Reason:         "incident: " + fmtSprintf(format, args...),
		CurrentVersion: currentVersion,
	}
}

// IsValidationError reports whether err is an incident validation failure.
func IsValidationError(err error) bool {
	var target *ValidationError
	return errors.As(err, &target)
}

// IsNotFoundError reports whether err is a missing-incident/event failure.
func IsNotFoundError(err error) bool {
	var target *NotFoundError
	return errors.As(err, &target)
}

// IsConflictError reports whether err is an incident conflict failure.
func IsConflictError(err error) bool {
	var target *ConflictError
	return errors.As(err, &target)
}

// CurrentVersionOf returns the version reported with a version conflict, or
// 0 when err is not a version conflict.
func CurrentVersionOf(err error) int {
	var target *ConflictError
	if errors.As(err, &target) {
		return target.CurrentVersion
	}
	return 0
}

// Creation is the normalized content of POST /incidents.
type Creation struct {
	ID       string
	Title    string
	Service  string
	Operator string
}

// Request is the normalized content of POST /incidents/{id}/actions.
type Request struct {
	IncidentID      string
	ActionID        string
	Operator        string
	ExpectedVersion int
	Type            string
	// Content carries the action payload:
	//   add_note    -> the note text
	//   link_event  -> the linked event id
	//   resolve     -> the reason
	//   reopen      -> the reason
	Content string
}

// CreateResult is returned by a successful create, including an idempotent
// replay.
type CreateResult struct {
	ID      string
	Status  string
	Version int
}

// ActionResult is returned by a successful action, including an idempotent
// replay.
type ActionResult struct {
	IncidentID string
	ActionID   string
	Version    int
}

// Entry is one committed item in an incident's history: the creation itself
// or a later action.
type Entry struct {
	ActionID string
	Operator string
	Action   string
	Content  string
	Version  int
	At       time.Time
}

// Incident is one committed snapshot, suitable for a single-version read.
type Incident struct {
	ID      string
	Title   string
	Service string
	Status  string
	Version int
	Links   []string
	History []Entry
}

// EventLookup resolves an event id without exposing the whole timeline, so
// incident handling never modifies events.
type EventLookup interface {
	// LookupEvent returns (service, true) for a stored event, or ("", false).
	LookupEvent(id string) (service string, ok bool)
}

// BeforeCommit persists one new record (creation or action) while the
// registry lock is held and before the in-memory state advances. A failure
// rejects the request without changing the incident.
type BeforeCommit func(record Record) error

// Registry is the concurrency-safe set of incidents.
type Registry struct {
	mu        sync.Mutex
	incidents map[string]*incidentState

	events       EventLookup
	beforeCommit BeforeCommit
	now          func() time.Time
}

// incidentState is the mutable state of one incident.
type incidentState struct {
	id       string
	title    string
	service  string
	status   string
	version  int
	links    []string
	linkSet  map[string]struct{}
	history  []Entry
	actions  map[string]committedAction
	creation creationRecord
}

// committedAction remembers a successful action's normalized request and the
// version the incident reached after it, so an identical retry can replay the
// first result even after the version has moved on.
type committedAction struct {
	request       Request
	resultVersion int
}

// Option configures a Registry at construction.
type Option func(*Registry)

// WithClock overrides the server clock, mainly for tests.
func WithClock(now func() time.Time) Option {
	return func(r *Registry) {
		if now != nil {
			r.now = now
		}
	}
}

// NewRegistry returns an empty registry. events resolves linked event ids and
// beforeCommit durably stores each accepted record.
func NewRegistry(events EventLookup, beforeCommit BeforeCommit, opts ...Option) *Registry {
	r := &Registry{
		incidents:     make(map[string]*incidentState),
		events:        events,
		beforeCommit: beforeCommit,
		now:           func() time.Time { return time.Now().UTC() },
	}
	for _, opt := range opts {
		opt(r)
	}
	return r
}

// Create accepts a new incident or replays an identical creation. A stored id
// presented with different normalized content conflicts.
func (r *Registry) Create(input Creation) (CreateResult, error) {
	creation := normalizeCreation(input)
	if err := creation.validate(); err != nil {
		return CreateResult{}, err
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	if existing, ok := r.incidents[creation.ID]; ok {
		if existing.creation.content != creation {
			return CreateResult{}, conflictErr(existing.version,
				"incident %q already exists with different content", creation.ID)
		}
		return CreateResult{ID: existing.id, Status: existing.status, Version: existing.version}, nil
	}

	at := r.now()
	state := &incidentState{
		id:      creation.ID,
		title:   creation.Title,
		service: creation.Service,
		status:  StatusOpen,
		version: 1,
		linkSet: make(map[string]struct{}),
		actions: make(map[string]committedAction),
		history: []Entry{{
			Operator: creation.Operator,
			Action:   ActionCreate,
			Version:  1,
			At:       at,
		}},
		creation: creationRecord{content: creation, at: at},
	}

	record := Record{Kind: RecordCreation, Creation: &creation, At: at}
	if r.beforeCommit != nil {
		if err := r.beforeCommit(record); err != nil {
			return CreateResult{}, err
		}
	}
	r.incidents[state.id] = state
	return CreateResult{ID: state.id, Status: state.status, Version: state.version}, nil
}

// Apply accepts one action or replays an identical one. Validation and all
// state checks happen under the registry lock, before persistence, so a
// rejected request leaves the incident untouched.
func (r *Registry) Apply(input Request) (ActionResult, error) {
	req, err := normalizeRequest(input)
	if err != nil {
		return ActionResult{}, err
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	state, ok := r.incidents[req.IncidentID]
	if !ok {
		return ActionResult{}, notFoundErr("incident %q not found", req.IncidentID)
	}

	if prior, repeated := state.actions[req.ActionID]; repeated {
		if prior.request != req {
			return ActionResult{}, conflictErr(state.version,
				"action %q already exists with different content", req.ActionID)
		}
		return ActionResult{
			IncidentID: state.id,
			ActionID:   prior.request.ActionID,
			Version:    prior.resultVersion,
		}, nil
	}

	// Every new action must target the version currently committed.
	if req.ExpectedVersion != state.version {
		return ActionResult{}, conflictErr(state.version,
			"expected version %d but incident %q is at version %d",
			req.ExpectedVersion, state.id, state.version)
	}

	nextVersion := state.version + 1
	switch req.Type {
	case ActionNote:
		// Always valid in open state.
	case ActionLinkEvent:
		if state.status != StatusOpen {
			return ActionResult{}, conflictErr(state.version,
				"cannot link an event to a %s incident", state.status)
		}
		if r.events == nil {
			return ActionResult{}, notFoundErr("event %q not found", req.Content)
		}
		service, found := r.events.LookupEvent(req.Content)
		if !found {
			return ActionResult{}, notFoundErr("event %q not found", req.Content)
		}
		if service != state.service {
			return ActionResult{}, conflictErr(state.version,
				"event %q belongs to service %q, not %q", req.Content, service, state.service)
		}
		if _, linked := state.linkSet[req.Content]; linked {
			return ActionResult{}, conflictErr(state.version,
				"event %q is already linked to incident %q", req.Content, state.id)
		}
	case ActionResolve:
		if state.status != StatusOpen {
			return ActionResult{}, conflictErr(state.version,
				"incident %q is already resolved", state.id)
		}
	case ActionReopen:
		if state.status != StatusResolved {
			return ActionResult{}, conflictErr(state.version,
				"incident %q is not resolved", state.id)
		}
	default:
		return ActionResult{}, validationErr("unknown action %q", req.Type)
	}

	at := r.now()
	record := Record{Kind: RecordAction, Action: &storedAction{request: req, at: at}}
	if r.beforeCommit != nil {
		if err := r.beforeCommit(record); err != nil {
			return ActionResult{}, err
		}
	}

	switch req.Type {
	case ActionLinkEvent:
		state.linkSet[req.Content] = struct{}{}
		state.links = append(state.links, req.Content)
	case ActionResolve:
		state.status = StatusResolved
	case ActionReopen:
		state.status = StatusOpen
	}
	state.version = nextVersion
	state.history = append(state.history, Entry{
		ActionID: req.ActionID,
		Operator: req.Operator,
		Action:   req.Type,
		Content:  req.Content,
		Version:  nextVersion,
		At:       at,
	})
	state.actions[req.ActionID] = committedAction{request: req, resultVersion: nextVersion}

	return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: nextVersion}, nil
}

// Get returns a point-in-time copy of one incident at its latest committed
// version. The copy's status, links, and history all belong to that version.
func (r *Registry) Get(id string) (Incident, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	state, ok := r.incidents[id]
	if !ok {
		return Incident{}, notFoundErr("incident %q not found", id)
	}
	return state.snapshot(), nil
}

func (s *incidentState) snapshot() Incident {
	links := slices.Clone(s.links)
	if links == nil {
		links = []string{}
	}
	history := make([]Entry, len(s.history))
	copy(history, s.history)
	return Incident{
		ID:      s.id,
		Title:   s.title,
		Service: s.service,
		Status:  s.status,
		Version: s.version,
		Links:   links,
		History: history,
	}
}

// normalizeCreation trims surrounding whitespace but keeps interior case, and
// leaves the fields set so equality checks compare normalized content.
func normalizeCreation(input Creation) creationRecord {
	return creationRecord{}
}

// trimNonEmpty trims s and returns an error when the result is empty.
func trimNonEmpty(field, value string) (string, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return "", validationErr("%s must not be empty", field)
	}
	return value, nil
}

// ensure maps is referenced for content comparisons elsewhere in the package.
var _ = maps.Equal[string, string]

