	return func(r *Registry) {
		if now != nil {
			r.now = now
		}
	}
}

// NewRegistry returns an empty registry. events resolves linked event ids and
// beforeCommit durably stores each accepted record.
func NewRegistry(events EventLookup, beforeCommit BeforeCommit, opts ...Option) *Registry {
	r := &Registry{
		incidents:     make(map[string]*incidentState),
		events:        events,
		beforeCommit: beforeCommit,
		now:           func() time.Time { return time.Now().UTC() },
	}
	for _, opt := range opts {
		opt(r)
	}
	return r
}

// Create accepts a new incident or replays an identical creation. A stored id
// presented with different normalized content conflicts.
func (r *Registry) Create(input Creation) (CreateResult, error) {
	creation := normalizeCreation(input)
	if err := creation.validate(); err != nil {
		return CreateResult{}, err
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	if existing, ok := r.incidents[creation.ID]; ok {
		if existing.creation.content != creation {
			return CreateResult{}, conflictErr(existing.version,
				"incident %q already exists with different content", creation.ID)
		}
		return CreateResult{ID: existing.id, Status: existing.status, Version: existing.version}, nil
	}

	at := r.now()
	state := &incidentState{
		id:      creation.ID,
		title:   creation.Title,
		service: creation.Service,
		status:  StatusOpen,
		version: 1,
		linkSet: make(map[string]struct{}),
		actions: make(map[string]committedAction),
		history: []Entry{{
			Operator: creation.Operator,
			Action:   ActionCreate,
			Version:  1,
			At:       at,
		}},
		creation: creationRecord{content: creation, at: at},
	}

	record := Record{Kind: RecordCreation, Creation: &creation, At: at}
	if r.beforeCommit != nil {
		if err := r.beforeCommit(record); err != nil {
			return CreateResult{}, err
		}
	}
	r.incidents[state.id] = state
	return CreateResult{ID: state.id, Status: state.status, Version: state.version}, nil
}

// Apply accepts one action or replays an identical one. Validation and all
// state checks happen under the registry lock, before persistence, so a
// rejected request leaves the incident untouched.
func (r *Registry) Apply(input Request) (ActionResult, error) {
	req, err := normalizeRequest(input)
	if err != nil {
		return ActionResult{}, err
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	state, ok := r.incidents[req.IncidentID]
	if !ok {
		return ActionResult{}, notFoundErr("incident %q not found", req.IncidentID)
	}

	if prior, repeated := state.actions[req.ActionID]; repeated {
		if prior.request != req {
			return ActionResult{}, conflictErr(state.version,
				"action %q already exists with different content", req.ActionID)
		}
		return ActionResult{
			IncidentID: state.id,
			ActionID:   prior.request.ActionID,
			Version:    prior.resultVersion,
		}, nil
	}

	// Every new action must target the version currently committed.
	if req.ExpectedVersion != state.version {
		return ActionResult{}, conflictErr(state.version,
			"expected version %d but incident %q is at version %d",
			req.ExpectedVersion, state.id, state.version)
	}

	nextVersion := state.version + 1
	switch req.Type {
	case ActionNote:
		// Always valid in open state.
	case ActionLinkEvent:
		if state.status != StatusOpen {
			return ActionResult{}, conflictErr(state.version,
				"cannot link an event to a %s incident", state.status)
		}
		if r.events == nil {
			return ActionResult{}, notFoundErr("event %q not found", req.Content)
		}
		service, found := r.events.LookupEvent(req.Content)
		if !found {
			return ActionResult{}, notFoundErr("event %q not found", req.Content)
		}
		if service != state.service {
			return ActionResult{}, conflictErr(state.version,
				"event %q belongs to service %q, not %q", req.Content, service, state.service)
		}
		if _, linked := state.linkSet[req.Content]; linked {
			return ActionResult{}, conflictErr(state.version,
				"event %q is already linked to incident %q", req.Content, state.id)
		}
	case ActionResolve:
		if state.status != StatusOpen {
			return ActionResult{}, conflictErr(state.version,
				"incident %q is already resolved", state.id)
		}
	case ActionReopen:
		if state.status != StatusResolved {
			return ActionResult{}, conflictErr(state.version,
				"incident %q is not resolved", state.id)
		}
	default:
		return ActionResult{}, validationErr("unknown action %q", req.Type)
	}

	at := r.now()
	record := Record{Kind: RecordAction, Action: &storedAction{request: req, at: at}}
	if r.beforeCommit != nil {
		if err := r.beforeCommit(record); err != nil {
			return ActionResult{}, err
		}
	}

	switch req.Type {
	case ActionLinkEvent:
		state.linkSet[req.Content] = struct{}{}
		state.links = append(state.links, req.Content)
	case ActionResolve:
		state.status = StatusResolved
	case ActionReopen:
		state.status = StatusOpen
	}
	state.version = nextVersion
	state.history = append(state.history, Entry{
		ActionID: req.ActionID,
		Operator: req.Operator,
		Action:   req.Type,
		Content:  req.Content,
		Version:  nextVersion,
		At:       at,
	})
	state.actions[req.ActionID] = committedAction{request: req, resultVersion: nextVersion}

	return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: nextVersion}, nil
}

// Get returns a point-in-time copy of one incident at its latest committed
// version. The copy's status, links, and history all belong to that version.
func (r *Registry) Get(id string) (Incident, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	state, ok := r.incidents[id]
	if !ok {
		return Incident{}, notFoundErr("incident %q not found", id)
	}
	return state.snapshot(), nil
}

func (s *incidentState) snapshot() Incident {
	links := slices.Clone(s.links)
	if links == nil {
		links = []string{}
	}
	history := make([]Entry, len(s.history))
	copy(history, s.history)
	return Incident{
		ID:      s.id,
		Title:   s.title,
		Service: s.service,
		Status:  s.status,
		Version: s.version,
		Links:   links,
		History: history,
	}
}

// normalizeCreation trims surrounding whitespace but keeps interior case, and
// leaves the fields set so equality checks compare normalized content.
func normalizeCreation(input Creation) creationRecord {
	return creationRecord{}
}

// trimNonEmpty trims s and returns an error when the result is empty.
func trimNonEmpty(field, value string) (string, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return "", validationErr("%s must not be empty", field)
	}
	return value, nil
}

// ensure maps is referenced for content comparisons elsewhere in the package.
var _ = maps.Equal[string, string]

