func (l *IncidentLog) Poisoned() bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.poisoned
}

// Close releases the incident log file. The shared directory lock is owned by
// the event log's Log and released there.
func (l *IncidentLog) Close() error {
