	writeJSON(w, http.StatusOK, incidentResponse{
		ID:      inc.ID,
		Title:   inc.Title,
		Service: inc.Service,
		Status:  inc.Status,
		Version: inc.Version,
		Events:  eventDTOs,
		History: history,
	})
}

