func TestConcurrentSameVersionOnlyOneSucceeds(t *testing.T) {
	reg, commit, _ := newTestRegistry(&fakeEvents{})
	_, _ = reg.Create(validCreation())

	const n = 32
	var wg sync.WaitGroup
	var success int64
	var mu sync.Mutex
	start := make(chan struct{})
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			req := Request{IncidentID: "INC-1", ActionID: "c", Operator: "o", ExpectedVersion: 1, Type: ActionNote, Content: "same"}
			res, err := reg.Apply(req)
			if err == nil {
				mu.Lock()
				success = res.Version
				mu.Unlock()
			}
		}(i)
	}
	close(start)
	wg.Wait()
	if success != 2 {
		t.Fatalf("expected one success at version 2, got %d", success)
	}
	inc, _ := reg.Get("INC-1")
	if inc.Version != 2 || len(inc.History) != 2 {
		t.Fatalf("exactly one action may land at a version: %+v", inc)
	}
	if commit.count() != 2 {
		t.Fatalf("exactly one action record may persist, got %d", commit.count())
	}
}

func TestConcurrentDistinctActionsSerialize(t *testing.T) {
	reg, _, _ := newTestRegistry(&fakeEvents{})
	_, _ = reg.Create(validCreation())

	const n = 20
	var wg sync.WaitGroup
	start := make(chan struct{})
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			// Spin on stale versions until the request lands or fails hard.
			for attempt := 0; attempt < n+1; attempt++ {
				inc, _ := reg.Get("INC-1")
				req := Request{IncidentID: "INC-1", ActionID: "note", Operator: "o",
					ExpectedVersion: inc.Version, Type: ActionNote, Content: "c"}
				// Unique action id per goroutine so replays do not coalesce.
				req.ActionID = "n" + itoa(i)
				if _, err := reg.Apply(req); err == nil {
					return
				} else if !IsConflictError(err) {
					t.Errorf("unexpected err: %v", err)
					return
				}
			}
		}(i)
	}
	close(start)
	wg.Wait()
	inc, _ := reg.Get("INC-1")
	if inc.Version != n+1 {
		t.Fatalf("all %d distinct actions should commit, version=%d", n, inc.Version)
	}
}

func itoa(i int) string {
	return strings.TrimSpace(string(rune('0' + i)))
}

